def next_smallest_palindrome(n: int) -> int:
    # If n < 8, the next palindrome is simply n+1
    if n < 8:
        return n + 1

    s = str(n + 1)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after numbers like 9, 99, 999 is 1001, 10001, ...
        return int('1' + ('0' * (length - 1)) + '1')

    def mirror_left_to_right(s: str) -> str:
        half = length // 2
        if length % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half + 1] + s[:half][::-1]

    palindrome = mirror_left_to_right(s)
    if int(palindrome) >= n + 1:
        return int(palindrome)

    # Increment the middle part and mirror again
    s_list = list(s)
    mid = (length - 1) // 2
    carry = 1

    # Increment the middle digit(s)
    while carry and mid >= 0:
        new_digit = (int(s_list[mid]) + carry)
        carry = new_digit // 10
        s_list[mid] = str(new_digit % 10)
        if length % 2 == 0:
            # For even length also increment the mirrored digit
            s_list[length - 1 - mid] = s_list[mid]
        mid -= 1

    # If carry is still 1, means we had something like 999 -> 1000, so handle that:
    if carry:
        # For example, length = 4, after increment: 10000, palindrome = 100001
        # But this case is handled by the all 9 check above, so just return
        return int('1' + ('0' * (length - 1)) + '1')

    s = ''.join(s_list)
    palindrome = mirror_left_to_right(s)
    return int(palindrome)

