        return True

    n = len(arr)
    # Check if arr is already sorted non-decreasing
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    # right shift by k means new array is arr[-k:] + arr[:-k]
    for k in range(1, n):
        shifted = arr[-k:] + arr[:-k]
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True
    return False

